import base64
from collections import UserDict
from os import PathLike
from typing import Any, Optional, Union

import urllib3
from urllib3 import Retry
from urllib3.exceptions import HTTPError

from thehive4py.__version__ import __version__
from thehive4py.errors import TheHiveError

DEFAULT_RETRY = Retry(
    total=5,
    backoff_factor=1,
    status_forcelist=[500, 502, 503, 504],
    allowed_methods=["GET", "POST", "PUT", "PATCH", "DELETE"],
    raise_on_status=False,
)


RetryValue = Union[Retry, int, None]
VerifyValue = Union[bool, str]


class _SessionJSONEncoder(jsonlib.JSONEncoder):
    """Custom JSON encoder class for TheHive session."""

    def default(self, o: Any):
        if isinstance(o, UserDict):
            return o.data
        return super().default(o)


class TheHiveSession:
    def __init__(
        self,
        url: str,
        apikey: Optional[str] = None,
        username: Optional[str] = None,
        password: Optional[str] = None,
        verify: VerifyValue = True,
        max_retries: RetryValue = DEFAULT_RETRY,
    ):
        self.hive_url = self._sanitize_hive_url(url)
        self.verify = verify

        # Create a PoolManager with retry configuration
        if max_retries is None:
            max_retries = DEFAULT_RETRY
        elif isinstance(max_retries, int):
            max_retries = Retry(total=max_retries)

        self.http = urllib3.PoolManager(
            retries=max_retries,
            cert_reqs='CERT_REQUIRED' if verify else 'CERT_NONE',
            ca_certs=verify if isinstance(verify, str) else None
        )

        self.headers = {
            "User-Agent": f"thehive4py/{__version__}"
        }

        if username and password:
            # Create basic auth header manually
            auth_str = f"{username}:{password}"
            auth_bytes = auth_str.encode('utf-8')
            auth_b64 = base64.b64encode(auth_bytes).decode('utf-8')
            self.headers["Authorization"] = f"Basic {auth_b64}"
        elif apikey:
            self.headers["Authorization"] = f"Bearer {apikey}"
        else:
            raise TheHiveError(
                "Either apikey or the username/password combination must be provided!"
            )

    def _sanitize_hive_url(self, hive_url: str) -> str:
        """Sanitize the base url for the client."""
        if hive_url.endswith("/"):
            return hive_url[:-1]
        return hive_url

    def make_request(
        self,
        method: str,
        path: str,
        params=None,
        data=None,
        json=None,
        files=None,
        download_path: Union[str, PathLike, None] = None,
    ) -> Any:
        endpoint_url = f"{self.hive_url}{path}"

        headers = {**self.headers}
        body = None

        if json:
            body = jsonlib.dumps(json, cls=_SessionJSONEncoder).encode('utf-8')
            headers["Content-Type"] = "application/json"
        elif data:
            body = data
            if isinstance(data, str):
                body = data.encode('utf-8')

        # Handle query parameters
        if params:
            # Convert params to query string
            from urllib.parse import urlencode
            query_string = urlencode(params, doseq=True)
            endpoint_url = f"{endpoint_url}?{query_string}"

        try:
            response = self.http.request(
                method,
                endpoint_url,
                body=body,
                headers=headers,
                preload_content=not bool(download_path),
            )

            return self._process_response(response, download_path=download_path)
        except HTTPError as e:
            # Convert urllib3 HTTPError to TheHiveError
            raise TheHiveError(message=str(e))

    def _process_response(
        self,
        response: urllib3.HTTPResponse,
        download_path: Union[str, PathLike, None] = None,
    ):
        if 200 <= response.status < 300:
            if download_path is None:
                return self._process_text_response(response)
            else:
                self._process_stream_response(
                    response=response, download_path=download_path
                )
                return None
        else:
            self._process_error_response(response=response)

    def _process_text_response(self, response: urllib3.HTTPResponse):
        try:
            json_data = jsonlib.loads(response.data.decode('utf-8'))
        except jsonlib.JSONDecodeError:
            json_data = None

        if json_data is None:
            return response.data.decode('utf-8')
        return json_data

    def _process_stream_response(
        self, response: urllib3.HTTPResponse, download_path: Union[str, PathLike]
    ):
        with open(download_path, "wb") as download_fp:
            for chunk in response.stream(4096):
                download_fp.write(chunk)

    def _process_error_response(self, response: urllib3.HTTPResponse):
        try:
            json_data = jsonlib.loads(response.data.decode('utf-8'))
        except jsonlib.JSONDecodeError:
            json_data = None

        if json_data is None:
            error_text = response.data.decode('utf-8')
        else:
            error_text = f"{json_data['type']} - {json_data['message']}"
        raise TheHiveError(message=error_text, response=response)"}

